
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_revapbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_revapbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.461643409991413e+01, 9.095756226010656e+01, 8.595425370042462e+01, 7.926185086104589e+01, 7.058836265844572e+01, 5.984208204123213e+01, 4.735043724770493e+01, 3.407405375528753e+01, 2.160510071339308e+01, 1.166222653598315e+01, 5.208516571142005e+00, 2.552830129685752e+00, 1.915781556216462e+00, 1.278634637139126e+00, 6.536159547937637e-01, 2.531809709443399e-01, 6.891293387281397e-02, 9.136451004200343e-03, 4.290758037972823e-04, 5.387155053909205e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


